public void addRemoveAddAgain() {
    ArrayDeque61B<Integer> d = new ArrayDeque61B<>();
    d.addLast(1);
    assertThat(d.removeFirst()).isEqualTo(1);
    assertThat(d.isEmpty()).isTrue();     // back to empty
    d.addFirst(2);                        // empty -> nonempty again
    assertThat(d.toList()).containsExactly(2).inOrder();
}

public class SLList {
    private static class IntNode {          // static: never needs the outer list
        int item; IntNode next;
        IntNode(int i, IntNode n) { item = i; next = n; }
    }
    private IntNode sentinel = new IntNode(-999, null);
    private int size = 0;

    public void addFirst(int x) {
        sentinel.next = new IntNode(x, sentinel.next);
        size += 1;
    }
    public void addLast(int x) {
        IntNode p = sentinel;               // never null, even when empty
        while (p.next != null) p = p.next;
        p.next = new IntNode(x, null);
        size += 1;
    }
    public void insert(int i, int x) {      // 0 <= i <= size
        IntNode p = sentinel;
        for (int k = 0; k < i; k++) p = p.next;   // p = node BEFORE position i
        p.next = new IntNode(x, p.next);
        size += 1;
    }
}

public void addLast(T x) {
    Node last = sentinel.prev;
    Node n = new Node(last, x, sentinel);   // prev, item, next
    last.next = n;
    sentinel.prev = n;
    size += 1;
}
public T removeFirst() {
    if (size == 0) return null;
    Node first = sentinel.next;
    sentinel.next = first.next;
    first.next.prev = sentinel;             // the line people forget
    size -= 1;
    return first.item;
}
public void insert(int index, T x) {        // 0 <= index <= size
    Node p = sentinel;                      // p = node before the slot
    if (index <= size / 2) {
        for (int i = 0; i < index; i++) p = p.next;
    } else {
        for (int i = size; i > index; i--) p = p.prev;
        p = p.prev;
    }
    Node n = new Node(p, x, p.next);
    p.next.prev = n;
    p.next = n;
    size += 1;
}

public class AList<T> {
    private T[] items = (T[]) new Object[8];   // new T[8] is a compile error
    private int size = 0;                      // next free slot
    public void addLast(T x) {
        if (size == items.length) resize(size * 2);
        items[size] = x;
        size += 1;
    }
    private void resize(int cap) {
        T[] a = (T[]) new Object[cap];
        System.arraycopy(items, 0, a, 0, size);
        items = a;
    }
    public T removeLast() {
        T x = items[size - 1];
        items[size - 1] = null;                // avoid loitering
        size -= 1;
        return x;
    }
}

public void addFirst(T x) {
    if (size == items.length) resize(items.length * 2);
    items[nextFirst] = x;
    nextFirst = Math.floorMod(nextFirst - 1, items.length);
    size += 1;
}
public T removeLast() {
    if (size == 0) return null;
    nextLast = Math.floorMod(nextLast - 1, items.length);
    T x = items[nextLast];
    items[nextLast] = null;
    size -= 1;
    return x;
}
private void resize(int cap) {          // unroll in logical order
    T[] a = (T[]) new Object[cap];
    for (int i = 0; i < size; i++) a[i] = get(i);
    items = a;
    nextFirst = cap - 1;                // just left of index 0 (wraps)
    nextLast = size;
}

