public void insert(int index, T x) {
    Node p = sentinel;                       // p will be the node BEFORE the slot
    if (index <= size / 2) {
        for (int i = 0; i < index; i++) p = p.next;
    } else {
        for (int i = size; i > index; i--) p = p.prev;  // p = node AT index
        p = p.prev;                                      // step to its predecessor
    }
    Node n = new Node(p, x, p.next);
    p.next.prev = n;
    p.next = n;
    size += 1;
}

int repair() {
    int idx = 0;
    Node p = sentinel;
    do {
        if (p.next.prev != p) {     // the forward link is trusted
            p.next.prev = p;
            return idx;
        }
        p = p.next; idx++;
    } while (p != sentinel);
    return -1;
}

public void reverse() {
    Node p = sentinel;
    do {
        Node t = p.next;
        p.next = p.prev;
        p.prev = t;
        p = t;                 // old next
    } while (p != sentinel);
}

private void resize(int cap) {
    T[] a = (T[]) new Object[cap];
    for (int i = 0; i < size; i++) {
        a[i] = items[(nextFirst + 1 + i) % items.length];
    }
    items = a;
    nextFirst = cap - 1;
    nextLast = size;
}

public void removeAdjDups() {
    IntNode p = sentinel.next;
    while (p != null && p.next != null) {
        if (p.next.item == p.item) { p.next = p.next.next; size -= 1; }
        else p = p.next;
    }
}
